@push('scripts')
<script>
$(function(){
    var columns=[{data:'namelink',name:'name'},{data:'email',name:'email'},{data:'work_number',name:'work_number'},{data:'usertype',name:'name'},{data:'action',name:'action',orderable:false,searchable:false}];
    var table=$('#users-table').DataTable({processing:true,serverSide:true,ajax:{url:'{!! route('users.data') !!}',type:'POST',headers:{'X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content')}},columns:columns,order:[],scrollX:false,autoWidth:false,pagingType:'full_numbers',dom:'<"w-full"t><"users-footer"<"users-footer-inner"ip>>',language:{emptyTable:'No team members found',info:'Showing _START_ to _END_ of _TOTAL_ entries',infoEmpty:'Showing 0 to 0 of 0 entries',paginate:{previous:'Previous',next:'Next'}}});
    $('#users-search').on('input',function(){table.search(this.value).draw()});$('#users-refresh').on('click',function(){table.ajax.reload(null,false)});
    window.openModal=function(id){$('#confirm_delete').attr('delete-id',id);new bootstrap.Modal(document.getElementById('user-delete-modal')).show()};
    function toggleSelect(trigger,target,value){$(trigger).on('change select2:select',function(){$(target).toggleClass('hidden',this.value!==value)})}toggleSelect('#handle_tasks','#assign_tasks','move_all_tasks');toggleSelect('#handle_leads','#assign_leads','move_all_leads');toggleSelect('#handle_clients','#assign_clients','move_all_clients');
    $('#confirm_delete').on('click',function(){$.ajax({url:"{{ route('users.delete') }}",type:'get',data:{id:$(this).attr('delete-id'),tasks:$('#handle_tasks').val(),leads:$('#handle_leads').val(),clients:$('#handle_clients').val(),task_user:$('#user_tasks').val(),lead_user:$('#user_leads').val(),client_user:$('#user_clients').val()},success:function(){location.reload()}})});
});
</script>
